const allMembers = recon.members || [];console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');console.log('  ≡ƒî╕ BANF Bosonto Utsob 2026 ΓÇö Pipeline Executor v2.0');console.log('  ≡ƒº¬ TEST MODE: All emails ΓåÆ ' + CONFIG.TEST_EMAIL);console.log('  ≡ƒôº Email processing: CONTINUOUS (poll-based)');console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ\n');// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// FAMILY / SPOUSE DETECTION// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction detectFamily(m) {  const result = {    spouseName: null, spouseEmail: null,    childrenCount: m.inferredKids || 0,    familyLabel: null, confidence: 'none',    allMembers: []  };  const emailKey = (m.email || '').toLowerCase();  // 1. User-confirmed overrides (highest priority)  if (SPOUSE_OVERRIDES[emailKey]) {    const ov = SPOUSE_OVERRIDES[emailKey];    result.spouseName = ov.spouseName;    result.spouseEmail = ov.spouseEmail;    result.confidence = 'confirmed';    result.allMembers.push({ name: ov.spouseName, relationship: 'spouse', email: ov.spouseEmail });  }  // 2. householdMembers (CRM-linked)  if (!result.spouseName && (m.householdMembers || []).length > 0) {    const hm = m.householdMembers[0];    result.spouseName = hm.displayName || `${hm.firstName} ${hm.lastName}`.trim();    result.spouseEmail = hm.email;    result.confidence = 'high';    result.allMembers.push({ name: result.spouseName, relationship: 'spouse', email: hm.email });  }  // 3. householdDisplayName "X & Y Lastname"  if (!result.spouseName && m.householdDisplayName) {    const match = m.householdDisplayName.match(/^(.+?)\s*&\s*(.+)/);    if (match) {      const memberFirst = (m.firstName || '').toLowerCase();      const spouse = match[1].toLowerCase().includes(memberFirst) ? match[2].trim() : match[1].trim();      if (spouse) { result.spouseName = spouse; result.confidence = 'medium'; result.allMembers.push({ name: spouse, relationship: 'spouse (from records)', email: null }); }    }  }  // 4. Payment rawName: "Name1 Da/ Name2 Di" or "Name1 / Name2"  if (!result.spouseName) {    for (const pay of (m.paymentRecords || [])) {      if (!pay.rawName) continue;      const slashMatch = pay.rawName.match(/^(.+?)\s*(?:Da\s*)?\/\s*(.+?)(?:\s*Di)?$/i);      if (slashMatch) {        const n1 = slashMatch[1].replace(/\s*Da\s*$/i, '').trim();        const n2 = slashMatch[2].replace(/\s*Di\s*$/i, '').trim();        const memberFirst = (m.firstName || '').toLowerCase();        const spouse = n1.toLowerCase().includes(memberFirst) ? n2 : n1;        if (spouse && spouse.length > 1) { result.spouseName = spouse; result.confidence = 'medium'; result.allMembers.push({ name: spouse, relationship: 'spouse (from payment records)', email: null }); break; }      }    }  }  // 5. familyMembers (extended family)  for (const fm of (m.familyMembers || [])) {    if (!result.allMembers.some(x => x.email === fm.email || x.name === fm.displayName)) {      result.allMembers.push({ name: fm.displayName, relationship: 'family member', email: fm.email });    }  }  // Build family label  if (result.spouseName && m.householdType === 'family') {    const kids = result.childrenCount;    result.familyLabel = `${m.firstName} & ${result.spouseName.split(' ')[0]} ${m.lastName} Family${kids > 0 ? ` (+${kids} child${kids > 1 ? 'ren' : ''})` : ''}`;  } else if (result.spouseName && m.householdType === 'couple') {    result.familyLabel = `${m.firstName} & ${result.spouseName.split(' ')[0]} ${m.lastName}`;  } else {    result.familyLabel = m.displayName;  }  return result;}/** * Get the correct FULL household membership amount for previous year. * CRM paymentRecords.amount sometimes stores per-person (halved) values. * householdMembershipAmount has the correct FULL household amount. */function getPreviousYearAmount(m) {  const hhAmt = m.householdMembershipAmount;  const prevPay = (m.paymentRecords || []).find(p => p.year === '2025-26');  if (hhAmt && hhAmt > 0) {    return { amount: hhAmt, category: m.householdMembershipCategory || 'Previous Plan', source: 'household_record', confident: true };  }  if (prevPay) {    const knownHalved = { 170: 340, 150: 300, 107.5: 215, 125: 250 };    if (knownHalved[prevPay.amount]) {      return { amount: knownHalved[prevPay.amount], category: prevPay.category, source: 'corrected_halved', confident: true };    }    return { amount: prevPay.amount, category: prevPay.category, source: 'payment_record', confident: true };  }  return null;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// BUILD PIPELINE MEMBERS// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉconst bosontoPipeline = [];const processedEmails = new Set();// Pass 1: Bosonto Evite respondentsfor (const m of allMembers) {  const bosonto = (m.eventAttendance || []).find(e => e.eventName && e.eventName.toLowerCase().includes('bosonto'));  if (!bosonto) continue;  const adults = parseInt(bosonto.adults) || 0;  const kids = parseInt(bosonto.kids) || 0;  const pay2026 = (m.paymentRecords || []).find(p => p.year === '2026-27');  const family = detectFamily(m);  const prevYear = getPreviousYearAmount(m);  bosontoPipeline.push({    email: m.email, firstName: m.firstName || '', lastName: m.lastName || '',    displayName: m.displayName || `${m.firstName} ${m.lastName}`,    phone: m.phone || '', address: m.address || '', city: m.city || 'Jacksonville', state: m.state || 'FL', zip: m.zip || '',    householdType: m.householdType || 'individual', householdDisplayName: m.householdDisplayName || '',    isECMember: m.isECMember || false,    eviteResponse: (bosonto.rsvp || '').toLowerCase(), eviteAdults: adults, eviteKids: kids,    paymentAmount: pay2026 ? pay2026.amount : 0, paymentStatus: pay2026 ? 'paid' : 'unpaid',    paymentSource: pay2026 ? pay2026.source : null, paymentSenderName: pay2026 ? pay2026.rawName : null,    paymentDate: pay2026 ? pay2026.date : null,    membershipCategory: pay2026 ? guessCategoryFromAmount(pay2026.amount, m.householdType) : null,    membershipTier: m.householdType === 'family' ? 'family' : m.householdType === 'couple' ? 'couple' : 'individual',    totalPaidAllTime: m.totalPaid || 0, membershipYears: m.membershipYears || [], previousCategories: m.membershipTypes || [],    family, previousYear: prevYear, inferredKids: m.inferredKids || 0, source: 'bosonto_evite'  });  processedEmails.add(m.email.toLowerCase());}// Pass 2: Members with 2026-27 payments but no Evite recordfor (const m of allMembers) {  if (processedEmails.has((m.email || '').toLowerCase())) continue;  const pay2026 = (m.paymentRecords || []).find(p => p.year === '2026-27');  if (!pay2026) continue;  const family = detectFamily(m);  const prevYear = getPreviousYearAmount(m);  bosontoPipeline.push({    email: m.email, firstName: m.firstName || '', lastName: m.lastName || '',    displayName: m.displayName || `${m.firstName} ${m.lastName}`,    phone: m.phone || '', address: m.address || '', city: m.city || 'Jacksonville', state: m.state || 'FL', zip: m.zip || '',    householdType: m.householdType || 'individual', householdD